@IsTest private class MapListObservation62 {
 private static Map<String,Object> fault(Exception error) {
  return new Map<String,Object>{'status'=>'exception','type'=>error.getTypeName(),'message'=>error.getMessage()};
 }
 private static void inspect(Boolean matching, Integer groupNumber) {
  Map<String,Object> out=new Map<String,Object>{'callerApi'=>'62.0','helperApi'=>'46.0','namespaceContext'=>'none','matching'=>matching};
  SObject seed;
  try {
   seed=matching ? (SObject)new GlyphCard__c(Name='Matching record') : (SObject)new AtlasCard__c(Name='Different record');
   insert seed;
   out.put('fixture',new Map<String,Object>{'status'=>'accepted','actualType'=>String.valueOf(seed.getSObjectType()),'hasId'=>seed.Id!=null});
  } catch(Exception error) {
   out.put('fixture',fault(error));
   emit(out,groupNumber); return;
  }
  List<SObject> raw=new List<SObject>{seed};
  List<GlyphCard__c> declared;
  Boolean helperAccepted=false;
  try {
   declared=MapListShelf46.read(raw);
   helperAccepted=true;
   out.put('helperCastReturn',new Map<String,Object>{'status'=>'accepted','declaredType'=>'List<GlyphCard__c>'});
  } catch(Exception error) { out.put('helperCastReturn',fault(error)); }
  if(!helperAccepted) {
   out.put('constructor',new Map<String,Object>{'status'=>'not-run','reason'=>'helper failed'});
   out.put('retrieval',new Map<String,Object>{'status'=>'not-run','reason'=>'helper failed'});
   out.put('putAll',new Map<String,Object>{'status'=>'not-run','reason'=>'helper failed'});
   emit(out,groupNumber); return;
  }
  try { out.put('listToken',new Map<String,Object>{'status'=>'accepted','value'=>String.valueOf(declared.getSObjectType())}); }
  catch(Exception error) { out.put('listToken',fault(error)); }
  Map<Id,GlyphCard__c> keyed;
  Boolean constructorAccepted=false;
  try {
   keyed=new Map<Id,GlyphCard__c>(declared);
   constructorAccepted=true;
   out.put('constructor',new Map<String,Object>{'status'=>'accepted'});
  } catch(Exception error) { out.put('constructor',fault(error)); }
  if(constructorAccepted) {
   try { out.put('mapSummary',new Map<String,Object>{'status'=>'accepted','size'=>keyed.size(),'containsSeed'=>keyed.containsKey(seed.Id)}); }
   catch(Exception error) { out.put('mapSummary',fault(error)); }
   try { out.put('mapToken',new Map<String,Object>{'status'=>'accepted','value'=>String.valueOf(keyed.getSObjectType())}); }
   catch(Exception error) { out.put('mapToken',fault(error)); }
   try {
    GlyphCard__c value=keyed.get(seed.Id);
    out.put('retrieval',new Map<String,Object>{'status'=>'accepted','declaredType'=>'GlyphCard__c','actualType'=>String.valueOf(value.getSObjectType()),'sameId'=>value.Id==seed.Id});
   } catch(Exception error) { out.put('retrieval',fault(error)); }
   try {
    Object boxed=keyed.get(seed.Id);
    SObject value=(SObject)boxed;
    out.put('boxedRetrieval',new Map<String,Object>{'status'=>'accepted','actualType'=>String.valueOf(value.getSObjectType()),'sameId'=>value.Id==seed.Id});
   } catch(Exception error) { out.put('boxedRetrieval',fault(error)); }
  } else { out.put('retrieval',new Map<String,Object>{'status'=>'not-run','reason'=>'constructor failed'}); }
  Map<Id,GlyphCard__c> appended=new Map<Id,GlyphCard__c>();
  try { appended.putAll(declared); out.put('putAll',new Map<String,Object>{'status'=>'accepted'}); }
  catch(Exception error) { out.put('putAll',fault(error)); }
  try { out.put('putAllSummary',new Map<String,Object>{'status'=>'accepted','size'=>appended.size(),'containsSeed'=>appended.containsKey(seed.Id)}); }
  catch(Exception error) { out.put('putAllSummary',fault(error)); }
  if(appended.containsKey(seed.Id)) {
   try {
    GlyphCard__c value=appended.get(seed.Id);
    out.put('putAllRetrieval',new Map<String,Object>{'status'=>'accepted','actualType'=>String.valueOf(value.getSObjectType()),'sameId'=>value.Id==seed.Id});
   } catch(Exception error) { out.put('putAllRetrieval',fault(error)); }
  }
  emit(out,groupNumber);
 }
 private static void emit(Map<String,Object> out, Integer groupNumber) {
  List<String> keys=groupNumber==1
   ? new List<String>{'fixture','helperCastReturn','listToken','constructor','mapSummary','mapToken'}
   : groupNumber==2 ? new List<String>{'helperCastReturn','retrieval','boxedRetrieval'}
   : new List<String>{'helperCastReturn','putAll','putAllSummary','putAllRetrieval'};
  Map<String,Object> selected=new Map<String,Object>();
  for(String key:keys) if(out.containsKey(key)) selected.put(key,out.get(key));
  System.assertEquals('NATIVE_MAP_OBSERVATION',JSON.serialize(selected));
 }
 @IsTest static void differentConstruct(){inspect(false,1);}
 @IsTest static void differentRetrieve(){inspect(false,2);}
 @IsTest static void differentPutAll(){inspect(false,3);}
 @IsTest static void matchingConstruct(){inspect(true,1);}
 @IsTest static void matchingRetrieve(){inspect(true,2);}
 @IsTest static void matchingPutAll(){inspect(true,3);}
}

